//! `membership/membership-ops-v1.json`: one signed op of each kind with fixed test keys, hash-context
//! vectors, and envelopes that must be rejected.
//!
//! The file is generated by `generate()` below. `fixture_is_current` fails when the file differs
//! from what the code produces; run with `BAKEN_REGEN_FIXTURES=1` to rewrite it. `vectors_verify`
//! checks the file on its own terms, the way a second implementation would.

// Fixture tables and their checks read top to bottom; splitting them hides the table.
#![allow(clippy::too_many_lines)]

mod common;

use common::{DagBuilder, body_entries, hex, key, key_named, raw_map, sign_raw, unhex};
use core_membership::crypto::{self, OP_ID_CONTEXT, ROTATE_POP_CONTEXT};
use core_membership::op::{Op, OpKind, key as field};
use core_membership::{MembershipLog, OpId, SignedOp};
use core_proto::bcbor::{self, Value};
use core_testkit::{contract_path, load_value};
use serde_json::{Value as Json, json};

const FIXTURE: &str = "membership/membership-ops-v1.json";
const TS: u64 = 1_764_158_400_000;

fn chain() -> DagBuilder {
    let mut b = DagBuilder::default();
    for desc in [
        json!({"op": "genesis", "kind": "genesis", "issuer": "N1", "caps_add": "preset:first_device",
               "name": "desk", "label": "home", "catalog_root": "000102030405060708090a0b0c0d0e0f",
               "ts_ms": TS}),
        json!({"op": "add", "kind": "add", "issuer": "N1", "parents": ["genesis"], "subject": "N2",
               "caps_add": "preset:phone", "name": "phone", "ts_ms": TS + 1}),
        json!({"op": "grant", "kind": "grant", "issuer": "N1", "parents": ["add"], "subject": "N2",
               "caps_add": ["node.execute"], "caps_remove": ["approve"], "ts_ms": TS + 2}),
        json!({"op": "revoke", "kind": "revoke", "issuer": "N1", "parents": ["grant"], "subject": "N3",
               "reason": "lost", "ts_ms": TS + 3}),
        json!({"op": "rotate", "kind": "rotate", "issuer": "N2", "parents": ["revoke"], "new_key": "N4",
               "ts_ms": TS + 4}),
        json!({"op": "policy_set", "kind": "policy_set", "issuer": "N1", "parents": ["rotate"],
               "policy": {"map": [[0, {"uint": 1}], [1, {"uint": 600_000}], [4, {"bool": false}]]},
               "ts_ms": TS + 5}),
        json!({"op": "catalog_root_move", "kind": "catalog_root_move", "issuer": "N1",
               "parents": ["policy_set"], "new_root": "101112131415161718191a1b1c1d1e1f",
               "prev_root": "000102030405060708090a0b0c0d0e0f", "ts_ms": TS + 6}),
    ] {
        b.add(&desc);
    }
    b
}

fn with_entry(mut entries: Vec<(u64, Vec<u8>)>, key: u64, value: &Value) -> Vec<(u64, Vec<u8>)> {
    entries.retain(|(k, _)| *k != key);
    entries.push((key, bcbor::encode(value)));
    entries.sort_by_key(|(k, _)| *k);
    entries
}

fn without(mut entries: Vec<(u64, Vec<u8>)>, key: u64) -> Vec<(u64, Vec<u8>)> {
    entries.retain(|(k, _)| *k != key);
    entries
}

/// Replaces the encoded value under `key` with `raw`, which need not be canonical.
fn replace_raw(entries: &mut [(u64, Vec<u8>)], key: u64, raw: Vec<u8>) {
    if let Some(entry) = entries.iter_mut().find(|(k, _)| *k == key) {
        entry.1 = raw;
    }
}

fn negative(name: &str, envelope: &[u8], stage: &str, error: &str) -> Json {
    json!({"name": name, "envelope": hex(envelope), "stage": stage, "error": error})
}

/// The envelopes that must be rejected, in the fixture's order: encoding, body fields, envelope
/// shape, insertion, then authorization.
fn negatives(b: &DagBuilder) -> Vec<Json> {
    let mut out = encoding_negatives(b);
    out.extend(body_negatives(b));
    out.extend(envelope_negatives(b));
    out.extend(insert_negatives(b));
    out.push(bad_pop_negative(b));
    out
}

/// A bad signature, a non-canonical body and an unsorted parent set.
fn encoding_negatives(b: &DagBuilder) -> Vec<Json> {
    let n1 = key(1);
    let mut bad_sig = bcbor::decode(&b.by_label["genesis"].envelope()).expect("envelope");
    if let Value::Array(parts) = &mut bad_sig
        && let Value::Bytes(sig) = &mut parts[1]
    {
        sig[63] ^= 0x01;
    }

    let mut non_canonical = body_entries(b.by_label["genesis"].op());
    replace_raw(&mut non_canonical, field::TS_MS, vec![0x18, 0x05]);

    let (low, high) = {
        let a = b.id("genesis");
        let c = b.id("add");
        if a < c { (a, c) } else { (c, a) }
    };
    let mut unsorted_parents = vec![0x82];
    unsorted_parents.extend(bcbor::encode(&Value::Bytes(high.as_bytes().to_vec())));
    unsorted_parents.extend(bcbor::encode(&Value::Bytes(low.as_bytes().to_vec())));
    let mut unsorted = body_entries(b.by_label["add"].op());
    replace_raw(&mut unsorted, field::PARENTS, unsorted_parents);

    vec![
        negative(
            "bad_signature",
            &bcbor::encode(&bad_sig),
            "decode",
            "bad_signature",
        ),
        negative(
            "non_canonical_body",
            &sign_raw(&raw_map(&non_canonical), &n1),
            "decode",
            "bad_encoding",
        ),
        negative(
            "unsorted_parents",
            &sign_raw(&raw_map(&unsorted), &n1),
            "decode",
            "bad_field",
        ),
    ]
}

/// One field changed in a canonical body.
enum Edit {
    Set(u64, Value),
    Drop(u64),
}

/// The body cases: (name, the chain op whose body is edited, the edit, the error).
fn body_cases() -> Vec<(&'static str, &'static str, Edit, &'static str)> {
    use Edit::{Drop, Set};
    let other_subject = Value::Bytes(key(5).node_id().as_bytes().to_vec());
    let bad_caps = Value::Array(vec![Value::Text("Admin".into())]);
    vec![
        (
            "unexpected_field",
            "add",
            Set(field::LABEL, Value::Text("x".into())),
            "unexpected_field",
        ),
        (
            "missing_field",
            "grant",
            Drop(field::CAPS_REMOVE),
            "missing_field",
        ),
        (
            "oversize",
            "add",
            Set(64, Value::Bytes(vec![0; 8_200])),
            "too_large",
        ),
        (
            "genesis_with_constellation",
            "genesis",
            Set(field::CONSTELLATION, Value::Bytes(vec![0xee; 32])),
            "unexpected_field",
        ),
        (
            "unknown_kind",
            "add",
            Set(field::KIND, Value::Uint(7)),
            "unknown_kind",
        ),
        (
            "bad_version",
            "add",
            Set(field::V, Value::Uint(2)),
            "bad_version",
        ),
        (
            "name_too_long",
            "add",
            Set(field::NAME, Value::Text("n".repeat(65))),
            "bad_field",
        ),
        (
            "bad_capability_string",
            "add",
            Set(field::CAPS_ADD, bad_caps),
            "bad_field",
        ),
        (
            "rotate_subject_not_issuer",
            "rotate",
            Set(field::SUBJECT, other_subject),
            "subject_not_issuer",
        ),
    ]
}

/// Canonical bodies with one field wrong, each signed by its issuer.
fn body_negatives(b: &DagBuilder) -> Vec<Json> {
    body_cases()
        .into_iter()
        .map(|(name, label, edit, error)| {
            let op = b.by_label[label].op();
            let entries = match edit {
                Edit::Set(key, value) => with_entry(body_entries(op), key, &value),
                Edit::Drop(key) => without(body_entries(op), key),
            };
            let signer = key_named(&common::name_of_node(&op.header.issuer));
            negative(
                name,
                &sign_raw(&raw_map(&entries), &signer),
                "decode",
                error,
            )
        })
        .collect()
}

/// Envelopes that are not `[body bstr, sig bstr64]`.
fn envelope_negatives(b: &DagBuilder) -> Vec<Json> {
    vec![
        negative(
            "envelope_not_array",
            &bcbor::encode(&Value::Map(std::collections::BTreeMap::new())),
            "decode",
            "bad_shape",
        ),
        negative(
            "short_signature",
            &bcbor::encode(&Value::Array(vec![
                Value::Bytes(b.by_label["add"].body().to_vec()),
                Value::Bytes(vec![0; 63]),
            ])),
            "decode",
            "bad_shape",
        ),
    ]
}

/// Well-formed ops the log refuses: another constellation's add and a foreign genesis.
fn insert_negatives(b: &DagBuilder) -> Vec<Json> {
    let mut foreign = b.by_label["add"].op().clone();
    foreign.header.constellation = Some(OpId::from_bytes([0xee; 32]));
    let mut other_genesis = b.by_label["genesis"].op().clone();
    other_genesis.header.issuer = key(2).node_id();
    vec![
        negative(
            "wrong_constellation",
            &SignedOp::sign(&foreign, &key(1)).expect("signs").envelope(),
            "insert",
            "constellation_mismatch",
        ),
        negative(
            "foreign_genesis",
            &SignedOp::sign(&other_genesis, &key(2))
                .expect("signs")
                .envelope(),
            "insert",
            "foreign_genesis",
        ),
    ]
}

/// A rotate whose proof of possession is signed by the wrong key: it decodes and inserts, and
/// authorization rejects it.
fn bad_pop_negative(b: &DagBuilder) -> Json {
    let constellation = b.constellation.expect("genesis");
    let mut bad_pop = b.by_label["rotate"].op().clone();
    bad_pop.header.issuer = key(1).node_id();
    bad_pop.header.parents = [b.id("catalog_root_move")].into();
    bad_pop.payload = core_membership::OpPayload::Rotate {
        new_key: key(6).node_id(),
        new_key_sig: key(7).sign(&crypto::rotate_pop_message(
            &key(1).node_id(),
            &key(6).node_id(),
            &constellation,
        )),
    };
    negative(
        "bad_pop",
        &SignedOp::sign(&bad_pop, &key(1)).expect("signs").envelope(),
        "authorize",
        "bad_proof_of_possession",
    )
}

fn generate() -> Json {
    let b = chain();
    let constellation = b.constellation.expect("genesis");
    let keys: Vec<Json> = (1..=7_u8)
        .map(|k| {
            json!({"name": format!("N{k}"), "seed": hex(&[k; 32]), "public": key(k).node_id().to_hex()})
        })
        .collect();
    let vectors: Vec<Json> = b
        .order
        .iter()
        .map(|label| {
            let signed = &b.by_label[label];
            json!({
                "name": label,
                "kind": signed.op().kind().name(),
                "issuer": common::name_of_node(&signed.op().header.issuer),
                "body": hex(signed.body()),
                "op_id": signed.id().to_string(),
                "sig": hex(signed.signature().as_bytes()),
                "envelope": hex(&signed.envelope()),
            })
        })
        .collect();
    let pop = crypto::rotate_pop_message(&key(2).node_id(), &key(4).node_id(), &constellation);
    json!({
        "contract": "membership/ops",
        "version": 1,
        "generator": "core/crates/core-membership/tests/op_vectors.rs (BAKEN_REGEN_FIXTURES=1 cargo test -p core-membership --test op_vectors)",
        "keys": keys,
        "constellation": constellation.to_string(),
        "hash_contexts": [
            {"context": OP_ID_CONTEXT, "input": "", "output": OpId::of_body(b"").to_string()},
            {"context": OP_ID_CONTEXT, "input": "616263", "output": OpId::of_body(b"abc").to_string()},
            {"context": ROTATE_POP_CONTEXT, "subject": "N2", "new_key": "N4",
             "constellation": constellation.to_string(), "output": hex(&pop)},
        ],
        "vectors": vectors,
        "invalid": negatives(&b),
    })
}

#[test]
fn fixture_is_current() {
    let generated = generate();
    if std::env::var_os("BAKEN_REGEN_FIXTURES").is_some() {
        let text = serde_json::to_string_pretty(&generated).expect("serializes") + "\n";
        // Write beside the fixture and rename over it, so `vectors_verify`, which runs in
        // parallel, never reads a half-written file.
        let path = contract_path(FIXTURE);
        let staged = path.with_extension("json.tmp");
        std::fs::write(&staged, text).expect("writes staged fixture");
        std::fs::rename(&staged, &path).expect("replaces fixture");
    }
    let on_disk = load_value(FIXTURE).expect("fixture loads");
    assert!(
        on_disk == generated,
        "{FIXTURE} is stale; regenerate with BAKEN_REGEN_FIXTURES=1"
    );
}

#[test]
fn vectors_verify() {
    let fixture = load_value(FIXTURE).expect("fixture loads");
    verify_keys(&fixture);
    let constellation = OpId::from_bytes(
        unhex(fixture["constellation"].as_str().expect("id"))
            .try_into()
            .expect("32"),
    );
    let log = verify_vectors(&fixture, constellation);
    verify_hash_contexts(&fixture, constellation);
    for vector in fixture["invalid"].as_array().expect("invalid") {
        verify_invalid(vector, &log);
    }
}

/// Every test key's public key follows from its seed.
fn verify_keys(fixture: &Json) {
    for k in fixture["keys"].as_array().expect("keys") {
        let name = k["name"].as_str().expect("name");
        let seed: [u8; 32] = unhex(k["seed"].as_str().expect("seed"))
            .try_into()
            .expect("32");
        assert_eq!(
            core_membership::NodeKey::from_seed(&seed)
                .node_id()
                .to_hex(),
            k["public"],
            "{name}"
        );
    }
}

/// Every vector decodes, re-encodes byte for byte and inserts; together they cover every kind and
/// all evaluate as valid. Returns the log holding them.
fn verify_vectors(fixture: &Json, constellation: OpId) -> MembershipLog {
    let mut log = MembershipLog::new(constellation);
    let mut kinds = Vec::new();
    for vector in fixture["vectors"].as_array().expect("vectors") {
        let name = vector["name"].as_str().expect("name");
        let signed = verify_vector(vector);
        kinds.push(signed.op().kind());
        log.insert(signed).expect(name);
    }
    for kind in [
        OpKind::Genesis,
        OpKind::Add,
        OpKind::Revoke,
        OpKind::Grant,
        OpKind::Rotate,
        OpKind::PolicySet,
        OpKind::CatalogRootMove,
    ] {
        assert!(kinds.contains(&kind), "a vector of every kind: {kind:?}");
    }
    let evaluation = log.evaluate();
    assert!(
        evaluation.rejections.is_empty(),
        "{:?}",
        evaluation.rejections
    );
    log
}

fn verify_vector(vector: &Json) -> SignedOp {
    let name = vector["name"].as_str().expect("name");
    let envelope = unhex(vector["envelope"].as_str().expect("envelope"));
    let signed = SignedOp::decode_envelope(&envelope).expect(name);
    assert_eq!(hex(signed.body()), vector["body"], "{name} body");
    assert_eq!(signed.id().to_string(), vector["op_id"], "{name} op id");
    assert_eq!(
        hex(signed.signature().as_bytes()),
        vector["sig"],
        "{name} sig"
    );
    assert_eq!(signed.envelope(), envelope, "{name} envelope re-encodes");
    assert_eq!(
        signed.op().encode(),
        signed.body(),
        "{name} body re-encodes"
    );
    assert_eq!(Op::decode(signed.body()).as_ref(), Ok(signed.op()));
    assert_eq!(signed.op().kind().name(), vector["kind"]);
    assert_eq!(
        signed.op().header.issuer,
        key_named(vector["issuer"].as_str().expect("issuer")).node_id()
    );
    signed
}

fn verify_hash_contexts(fixture: &Json, constellation: OpId) {
    for context in fixture["hash_contexts"].as_array().expect("contexts") {
        if context["context"] == OP_ID_CONTEXT {
            let input = unhex(context["input"].as_str().expect("input"));
            assert_eq!(OpId::of_body(&input).to_string(), context["output"]);
        } else {
            let message = crypto::rotate_pop_message(
                &key_named(context["subject"].as_str().expect("subject")).node_id(),
                &key_named(context["new_key"].as_str().expect("new_key")).node_id(),
                &constellation,
            );
            assert_eq!(hex(&message), context["output"]);
        }
    }
}

/// An invalid envelope fails at its stage with its code: decoding, inserting into `log`, or
/// authorization in the evaluation of `log` plus the op.
fn verify_invalid(vector: &Json, log: &MembershipLog) {
    let name = vector["name"].as_str().expect("name");
    let envelope = unhex(vector["envelope"].as_str().expect("envelope"));
    let expected = vector["error"].as_str().expect("error");
    let decoded = SignedOp::decode_envelope(&envelope);
    match vector["stage"].as_str().expect("stage") {
        "decode" => assert_eq!(decoded.expect_err(name).code(), expected, "{name}"),
        "insert" => {
            let error = log.clone().insert(decoded.expect(name)).expect_err(name);
            assert_eq!(error.code(), expected, "{name}");
        }
        "authorize" => {
            let signed = decoded.expect(name);
            let mut extended = log.clone();
            extended.insert(signed.clone()).expect(name);
            let evaluation = extended.evaluate();
            assert_eq!(
                evaluation
                    .rejections
                    .get(&signed.id())
                    .map(core_membership::Rejection::code),
                Some(expected),
                "{name}"
            );
        }
        other => panic!("unknown stage {other}"),
    }
}
